{
  "command": "bun .kiro/tools/aidlc.ts engine orchestrate next --resume",
  "__tool_use_purpose": "Resume the AI-DLC workflow via the engine"
}

{
  "__tool_use_purpose": "Continue with the rules receipt as the directive says",
  "command": "bun .kiro/tools/aidlc-orchestrate.ts continue Wn_wrIsW"
}

{
  "operations": [
    {
      "mode": "Line",
      "path": ".kiro/aidlc-common/stages/ideation/intent-capture.md"
    },
    {
      "mode": "Directory",
      "path": "aidlc/spaces/default/intents/261102-add-an-optional",
      "depth": 3
    },
    {
      "mode": "Line",
      "path": "aidlc/spaces/default/intents/261102-add-an-optional/aidlc-state.md"
    },
    {
      "mode": "Line",
